<?php require __DIR__.'/../includes/bootstrap.php'; require_login(); require __DIR__.'/../includes/layout.php'; if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$type=post('type');$desc=post('description');$q=$db->prepare('UPDATE settings SET description=? WHERE type=?');$q->bind_param('ss',$desc,$type);$q->execute();flash('Setting updated.');redirect('settings.php');}$rows=$db->query("SELECT * FROM settings ORDER BY type"); page_header('Settings',['Dashboard'=>'dashboard.php']); ?><div class="panel table-wrap"><table class="data"><tr><th>Type</th><th>Description</th><th>Save</th></tr><?php while($r=$rows->fetch_assoc()): ?><tr><form method="post"><td><?=e($r['type'])?><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="type" value="<?=e($r['type'])?>"></td><td><input name="description" value="<?=e($r['description'])?>"></td><td><button class="btn">Save</button></td></form></tr><?php endwhile; ?></table></div><?php page_footer(); ?>